/**
 *  Reconciled state of a `PackOrigin.missing_mods` entry against the
 *  installed jars. Computed by `compute_status`.
 */
export type MissingModState = 
/**  The exact file the pack pinned is installed. */
"installed" | 
/**  The mod is installed, but not the pinned file — a different version. */
"different_version" | 
/**  No installed jar matches this mod by any signal. */
"missing" | 
/**
 *  No pinned/different file is installed, but the user installed a
 *  substitute from another source (e.g. Modrinth) and we recorded the
 *  link in `PackOrigin.resolved_missing`. Treated as resolved, but
 *  surfaced distinctly so the UI does not claim the pinned file is present.
 */
"substituted";

/**
 *  One `PackOrigin.missing_mods` entry paired with its live
 *  classification — `installed` (the pinned file), `different_version`
 *  (the mod is present, but not the pinned file), `missing` (no matching
 *  jar), or `substituted` (the user installed an alternative from another
 *  source, recorded in `PackOrigin.resolved_missing`).
 *  Computed by `compute_status`; consumed by the imported-pack drawer
 *  and the Overview indicator.
 */
export type MissingModStatus = {
	entry: ModpackUnresolvable,
	state: MissingModState,
};

/**  One installed mod's compatibility result for a target (mc, loader). */
export type ModCompat = {
	/**  SHA-1 of the installed jar — the primary identity key in the registry. */
	sha1: string,
	/**  Display name from the registry. */
	name: string,
	status: ModCompatStatus,
};

/**
 *  The compatibility status of one installed mod against a target
 *  Minecraft version + loader combination.
 */
export type ModCompatStatus = 
/**
 *  At least one platform version exists for the target (mc, loader).
 *  `available_version` is the version number of the newest match when
 *  present (versions are returned newest-first by the platform layer).
 */
{ status: "compatible"; available_version: string | null } | 
/**
 *  The platform responded successfully but returned zero versions for
 *  the target (mc, loader) — the mod has no release for that combination.
 */
{ status: "incompatible" } | 
/**
 *  The platform query failed (network error, missing CurseForge key,
 *  project delisted / 404). A fetch error must NOT be read as
 *  incompatible — the user should be told we simply don't know.
 */
{ status: "unknown" };

